/**
 * The renderable half of the catalog. Kept separate from `catalog.ts` so the
 * wire manifest stays dependency-free and can be handed to the sidecar as plain
 * JSON.
 */
export const NODE_COMPONENTS: Record<string, ComponentType<NodeProps>> = {
  stack: Stack,
  grid: Grid,
  heading: Heading,
  text: Text,
  list: ListBlock,
  stat: Stat,
  meter: Meter,
  callout: Callout,
  divider: Divider,

  "outcome-card": OutcomeCard,
  "opportunity-board": OpportunityBoard,
  "impact-simulation": ImpactSimulation,
  "evidence-quote": EvidenceQuote,
  "job-map": JobMap,
  "decision-record": DecisionRecord,
};
import type { ReactNode } from "react";

import { readActions, useUiActions, type UiAction } from "./actions";
import type { UiNode } from "./protocol";
import { num, str, tone, type Tone } from "./props";
import { RichText } from "./RichText";

export interface NodeProps {
  node: UiNode;
  renderChildren: (children: UiNode[]) => ReactNode;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/* ------------------------------------------------------------------ */
/* Shared pieces                                                       */
/* ------------------------------------------------------------------ */

export function ActionRow({ actions }: { actions: UiAction[] }) {
  const dispatcher = useUiActions();
  if (!dispatcher || actions.length === 0) {
    return null;
  }

  return (
    <div className="ui-actions">
      {actions.map((action, index) => (
        <button
          key={`${action.label}-${index}`}
          type="button"
          className={`ui-action ui-action--${action.tone}`}
          disabled={dispatcher.busy}
          onClick={() => dispatcher.onIntent(action.intent)}
        >
          {action.label}
        </button>
      ))}
    </div>
  );
}

export function MeterBar({
  label,
  value,
  max = 10,
  tone: barTone = "neutral",
}: {
  label: string;
  value: number;
  max?: number;
  tone?: Tone;
}) {
  const pct = clamp((value / max) * 100, 0, 100);
  return (
    <div className="ui-meter">
      <div className="ui-meter__head">
        <span>{label}</span>
        <span className="ui-meter__value">
          {value}/{max}
        </span>
      </div>
      <div
        className="ui-meter__track"
        role="meter"
        aria-label={label}
        aria-valuemax={max}
        aria-valuemin={0}
        aria-valuenow={value}
      >
        <span className={`ui-meter__fill ui-tone-bg--${barTone}`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

export function ScorePill({ tone: pillTone, children }: { tone: Tone; children: ReactNode }) {
  return <span className={`ui-pill ui-pill--${pillTone}`}>{children}</span>;
}

/* ------------------------------------------------------------------ */
/* Layout                                                              */
/* ------------------------------------------------------------------ */

export function Stack({ node, renderChildren }: NodeProps) {
  const direction = str(node.props, "direction", "vertical");
  const gap = str(node.props, "gap", "md");
  return (
    <div className={`ui-stack ui-stack--${direction} ui-gap--${gap}`}>
      {renderChildren(node.children)}
      <ActionRow actions={readActions(node.props)} />
    </div>
  );
}

export function Grid({ node, renderChildren }: NodeProps) {
  const columns = num(node.props, "columns", 2);
  const gap = str(node.props, "gap", "md");
  return (
    <div className={`ui-grid ui-grid--${columns} ui-gap--${gap}`}>{renderChildren(node.children)}</div>
  );
}

/* ------------------------------------------------------------------ */
/* Atoms                                                               */
/* ------------------------------------------------------------------ */

export function Heading({ node }: NodeProps) {
  const text = str(node.props, "text");
  const level = num(node.props, "level", 2);
  const Tag = level <= 2 ? "h3" : "h4";
  return <Tag className="ui-heading">{text}</Tag>;
}

export function Text({ node }: NodeProps) {
  const text = str(node.props, "text");
  const textTone = str(node.props, "tone", "default");
  return (
    <div className={textTone === "default" ? "ui-text" : `ui-text ui-text--${textTone}`}>
      <RichText text={text} />
    </div>
  );
}

export function ListBlock({ node }: NodeProps) {
  const raw = node.props.items;
  const items = Array.isArray(raw) ? raw.filter((item): item is string => typeof item === "string") : [];
  const marker = str(node.props, "marker", "dot");
  const Tag = marker === "number" ? "ol" : "ul";

  return (
    <Tag className={`ui-list ui-list--${marker}`}>
      {items.map((item, index) => (
        <li key={`${index}-${item.slice(0, 12)}`}>{item}</li>
      ))}
    </Tag>
  );
}

export function Stat({ node }: NodeProps) {
  const label = str(node.props, "label");
  const value = str(node.props, "value");
  const delta = str(node.props, "delta");
  const statTone = tone(node.props);
  return (
    <div className={`ui-stat ui-tone--${statTone}`}>
      <div className="ui-stat__label">{label}</div>
      <div className="ui-stat__value">{value}</div>
      {delta ? <div className="ui-stat__delta">{delta}</div> : null}
    </div>
  );
}

export function Meter({ node }: NodeProps) {
  const label = str(node.props, "label");
  const value = num(node.props, "value", 0);
  const max = num(node.props, "max", 10);
  return <MeterBar label={label} value={value} max={max} tone={tone(node.props)} />;
}

export function Callout({ node }: NodeProps) {
  const calloutTone = tone(node.props, "info");
  const title = str(node.props, "title");
  const body = str(node.props, "body");
  return (
    <aside className={`ui-callout ui-callout--${calloutTone}`}>
      {title ? <div className="ui-callout__title">{title}</div> : null}
      <div className="ui-callout__body">
        <RichText text={body} />
      </div>
    </aside>
  );
}

export function Divider() {
  return <hr className="ui-divider" />;
}

/**
 * The wire contract for agent-composed UI.
 *
 * A payload is a tree of `{ type, props, children }` nodes validated against a
 * catalog manifest. The manifest is plain JSON Schema (draft 2020-12 subset),
 * so the same document can be handed to the model as a tool schema and used
 * here to validate what comes back. Nothing is eval'd, no HTML is injected, and
 * every node is bounded before it can reach React.
 *
 * Parsing is deliberately forgiving where it is safe (unknown props are
 * stripped, unknown component types degrade to a visible fallback) and strict
 * where it matters (structure, required props, and size ceilings).
 */

export const UI_LIMITS = {
  maxDepth: 12,
  maxNodes: 200,
  maxStringLength: 2000,
  maxChildren: 32,
  maxActions: 40,
} as const;

/** A JSON Schema subset: enough to describe every prop in the catalog. */
export interface UiPropSchema {
  type?: "string" | "number" | "integer" | "boolean" | "array" | "object";
  description?: string;
  enum?: readonly string[];
  minimum?: number;
  maximum?: number;
  items?: UiPropSchema;
  properties?: Record<string, UiPropSchema>;
  required?: readonly string[];
  minItems?: number;
  maxItems?: number;
}

export interface UiCatalogEntry {
  type: string;
  kind: "layout" | "leaf";
  description: string;
  acceptsChildren: boolean;
  props: UiPropSchema;
}

export interface UiCatalogManifest {
  version: 1;
  components: UiCatalogEntry[];
}

export interface UiNode {
  type: string;
  props: Record<string, unknown>;
  children: UiNode[];
  /** Set when the manifest has no component for this type. */
  unsupported?: boolean;
}

export type ParseResult = { ok: true; node: UiNode } | { ok: false; reason: string };

type ValueResult = { ok: true; value: unknown } | { ok: false };

interface ParseState {
  entries: Map<string, UiCatalogEntry>;
  nodes: number;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function catalogIndex(manifest: UiCatalogManifest): Map<string, UiCatalogEntry> {
  return new Map(manifest.components.map((entry) => [entry.type, entry]));
}

function ok(value: unknown): ValueResult {
  return { ok: true, value };
}

const INVALID: ValueResult = { ok: false };

function validateValue(raw: unknown, schema: UiPropSchema, depth: number): ValueResult {
  if (depth > UI_LIMITS.maxDepth + 4) {
    return INVALID;
  }

  if (schema.enum) {
    return typeof raw === "string" && schema.enum.includes(raw) ? ok(raw) : INVALID;
  }

  switch (schema.type) {
    case "string":
      if (typeof raw !== "string" || raw.length > UI_LIMITS.maxStringLength) {
        return INVALID;
      }
      return ok(raw);

    case "number":
    case "integer": {
      if (typeof raw !== "number" || !Number.isFinite(raw)) {
        return INVALID;
      }
      if (schema.type === "integer" && !Number.isInteger(raw)) {
        return INVALID;
      }
      if (schema.minimum !== undefined && raw < schema.minimum) {
        return INVALID;
      }
      if (schema.maximum !== undefined && raw > schema.maximum) {
        return INVALID;
      }
      return ok(raw);
    }

    case "boolean":
      return typeof raw === "boolean" ? ok(raw) : INVALID;

    case "array": {
      if (!Array.isArray(raw)) {
        return INVALID;
      }
      if (schema.minItems !== undefined && raw.length < schema.minItems) {
        return INVALID;
      }
      if (schema.maxItems !== undefined && raw.length > schema.maxItems) {
        return INVALID;
      }
      const items: unknown[] = [];
      for (const entry of raw) {
        const validated = schema.items ? validateValue(entry, schema.items, depth + 1) : ok(entry);
        if (!validated.ok) {
          return INVALID;
        }
        items.push(validated.value);
      }
      return ok(items);
    }

    case "object": {
      if (!isPlainObject(raw)) {
        return INVALID;
      }
      const result = validateProps(raw, schema, depth + 1);
      return result.ok ? ok(result.value) : INVALID;
    }

    default:
      return INVALID;
  }
}

function validateProps(
  raw: Record<string, unknown>,
  schema: UiPropSchema,
  depth: number,
): { ok: true; value: Record<string, unknown> } | { ok: false } {
  const properties = schema.properties ?? {};
  const result: Record<string, unknown> = {};

  for (const key of schema.required ?? []) {
    if (!(key in raw)) {
      return { ok: false };
    }
  }

  for (const [key, value] of Object.entries(raw)) {
    const propertySchema = properties[key];
    if (!propertySchema) {
      // Unknown props are stripped rather than trusted.
      continue;
    }
    const validated = validateValue(value, propertySchema, depth);
    if (!validated.ok) {
      if ((schema.required ?? []).includes(key)) {
        return { ok: false };
      }
      continue;
    }
    result[key] = validated.value;
  }

  return { ok: true, value: result };
}

function describePropFailure(entry: UiCatalogEntry, key: string): string {
  const schema = entry.props.properties?.[key];
  if (!schema) {
    return `unknown prop "${key}"`;
  }
  if (schema.enum) {
    return `prop "${key}" must be one of ${schema.enum.join(", ")}`;
  }
  if (schema.type === "number" || schema.type === "integer") {
    const bounds =
      schema.minimum !== undefined || schema.maximum !== undefined
        ? ` between ${schema.minimum ?? "-∞"} and ${schema.maximum ?? "∞"}`
        : "";
    return `prop "${key}" must be a ${schema.type}${bounds}`;
  }
  if (schema.type === "array") {
    return `prop "${key}" must be an array of valid items`;
  }
  if (schema.type === "object") {
    return `prop "${key}" must be an object with the documented fields`;
  }
  if (schema.type === "boolean") {
    return `prop "${key}" must be a boolean`;
  }
  return `prop "${key}" must be a ${schema.type ?? "valid value"}`;
}

function parseNode(raw: unknown, depth: number, state: ParseState): ParseResult {
