"""The no-LLM path, upgraded from a text fallback to a designed demo.

A new user who has not connected a model yet should still see what the product
is. These replies use the same catalog the model uses, so every card type has a
live example that CI can validate.
"""

from __future__ import annotations

from typing import Any

LOCAL_NOTE = (
    "\n\n*Running in local mode. Start an OpenAI-compatible model at "
    "`http://localhost:8001/v1` for full autonomous completions.*"
)

IDLE_REPLY = (
    'I heard: **"{user_input}"**.\n\n'
    "In The Living Studio every idea is judged against human outcomes instead of "
    "story points. Here is the landscape you are working in — the scores above 10 are "
    "the ones worth building." + LOCAL_NOTE
)

JOB_MAP_STEPS: list[dict[str, str]] = [
    {"name": "Define what success means", "stage": "define"},
    {"name": "Locate the inputs and the people", "stage": "locate"},
