def simulation_spec() -> dict[str, Any]:
    return {
        "type": "impact-simulation",
        "props": {
            "outcome": {
                "id": "O-1",
                "statement": "Minimize the time it takes to propagate secrets across environments",
            },
            "bet": "A zero-touch secret sync daemon that follows the deploy, not the calendar",
            "before": [
                "45 minutes of copy-paste per rotation",
                "14% of deploys fail on configuration drift",
                "400 teams carry the same manual ritual",
            ],
            "after": [
                "Under 30 seconds, ambient and unattended",
                "Zero human steps in the happy path",
                "3,000 engineer-hours returned every month",
            ],
            "metrics": [
                {"label": "Time to value", "value": "-90%", "delta": "Friction removed"},
                {"label": "Satisfaction", "value": "8.9 / 10", "delta": "+5.8 points"},
                {"label": "Risk", "value": "Low", "delta": "Non-breaking"},
            ],
            "verdict": "Build it. The friction is measurable, recurring, and entirely avoidable.",
            "actions": [
                {
                    "label": "Write the decision record",
                    "intent": "Draft a Product Decision Record for the zero-touch secret sync bet.",
                    "tone": "primary",
                }
            ],
        },
    }


def evidence_spec() -> dict[str, Any]:
    return {
        "type": "evidence-quote",
        "props": {
            "source": "Gong call #104 — FinTech Corp",
            "quote": (
                "A junior engineer pushed code that failed staging because the Stripe "
                "secret wasn't copied over. It took three seniors two hours to find "
                "out why the cluster wouldn't start. There has to be a better way "
