                }
            ],
        },
    }


def offline_reply(user_input: str) -> tuple[str, list[dict[str, Any]]]:
    """Return prose plus the surfaces that carry the evidence better than words."""
    lower = user_input.lower()

    if any(term in lower for term in ("guideline", "framework", "stage")):
        return (
            "Outcome-Driven Innovation moves in five moves. Here is the job, mapped "
