            kind=body.kind,
            text=body.text,
            data=body.data,
            confidence=body.confidence,
            source_turn=body.source_turn,
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {"observation": observation}


@router.patch("/memory/observations/{observation_id}")
def patch_observation(
    observation_id: str, body: ObservationUpdate, request: Request
) -> dict:
    try:
        observation = _memory(request).update_observation(
            observation_id, status=body.status, text=body.text
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    if observation is None:
        raise HTTPException(status_code=404, detail="Observation not found")
    return {"observation": observation}


