  payload: ObservationCreatePayload,
): Promise<Observation> {
  const body = await postJson<{ observation: Observation }>(
    "/api/memory/observations",
    payload,
  );
  return body.observation;
}

export async function updateObservation(
  observationId: string,
  payload: ObservationUpdatePayload,
): Promise<Observation> {
  const body = await patchJson<{ observation: Observation }>(
    `/api/memory/observations/${encodeURIComponent(observationId)}`,
    payload,
  );
  return body.observation;
}

