function partsFromStored(parts: StoredChatPart[]): ChatPart[] {
  const restored: ChatPart[] = [];
  for (const part of parts) {
    if (part.kind === "text") {
      if (!part.text) {
        continue;
      }
      const last = restored[restored.length - 1];
      if (last?.kind === "text") {
        restored[restored.length - 1] = { kind: "text", text: last.text + part.text };
      } else {
        restored.push({ kind: "text", text: part.text });
      }
    } else if (part.kind === "ui") {
      const parsed = parseUiSpec(part.spec, CATALOG_MANIFEST);
      if (parsed.ok) {
        restored.push({ kind: "ui", id: part.id, node: parsed.node });
      }
    }
  }
  return restored;
}

function conversationToMessages(conversation: StoredConversation): ChatMessage[] {
  return conversation.turns
    .map((turn) => {
      let parts = partsFromStored(turn.parts);
      if (parts.length === 0 && turn.content) {
        parts = [{ kind: "text", text: turn.content }];
      }
      return { role: turn.role, content: turn.content, parts };
    })
    .filter((message) => message.parts.length > 0);
}

