import { useStudio } from "../../state/StudioContext";
import { DirectCapture } from "./DirectCapture";
import { EvidenceStream } from "./EvidenceStream";
import { ImpactSim } from "./ImpactSim";
import { JobMap } from "./JobMap";
import { MemoryPanel } from "./MemoryPanel";
import { OpportunityLandscape } from "./OpportunityLandscape";

interface TabDef {
  id: string;
  label: string;
}

const TABS: TabDef[] = [
  { id: "landscape", label: "Your next move" },
  { id: "memory", label: "What I've learned" },
  { id: "jobmap", label: "How the work happens" },
  { id: "impact", label: "What changes" },
  { id: "evidence", label: "The evidence" },
  { id: "capture", label: "Add what you know" },
];

function renderPanel(tab: string) {
  switch (tab) {
    case "memory":
      return <MemoryPanel />;
    case "jobmap":
      return <JobMap />;
    case "impact":
      return <ImpactSim />;
    case "evidence":
      return <EvidenceStream />;
    case "capture":
      return <DirectCapture />;
    case "landscape":
    default:
      return <OpportunityLandscape />;
  }
}

export function CanvasTabs() {
  const { canvas, canvasLoading, canvasCached, activeTab, setActiveTab, engagementLevel } =
    useStudio();

  const showTabs = engagementLevel >= 1;

  return (
    <div>
      {showTabs && (
        <div className="studio-card" role="status" aria-live="polite">
          {canvasLoading ? (
            <span>Getting your workspace ready…</span>
          ) : canvas?.source === "seed" ? (
            <span>You're looking at example data. Nothing here is yours yet.</span>
          ) : (
            <span>Your workspace is ready.</span>
          )}
          {canvasCached && !canvasLoading ? (
            <span className="source-badge"> · refreshing in the background</span>
          ) : null}
        </div>
      )}

      {showTabs && (
        <div className="studio-tabs__list" role="tablist" aria-label="Your workspace">
          {TABS.map((tab) => (
            <button
              key={tab.id}
              type="button"
              role="tab"
              id={`tab-${tab.id}`}
              className="studio-tab"
              aria-selected={activeTab === tab.id}
              aria-controls={`panel-${tab.id}`}
              onClick={() => setActiveTab(tab.id)}
            >
              {tab.label}
            </button>
          ))}
        </div>
      )}

      {showTabs && (
        <div role="tabpanel" id={`panel-${activeTab}`} aria-labelledby={`tab-${activeTab}`}>
          {renderPanel(activeTab)}
        </div>
      )}
    </div>
  );
}

