  render_ui: "Showing your work",
  remember: "Taking a note",
};

input.oldString:
useEffect(() => {
  if (messages.length > 1 && engagementLevel === 0) {
    setEngagementLevel(1);
  }
}, [messages.length, engagementLevel, setEngagementLevel]);

input.newString:
useEffect(() => {
  const hasSurface = messages.some((message) =>
    message.parts.some((part) => part.kind === "ui" && part.id !== "welcome"),
  );
  if (hasSurface && engagementLevel === 0) {
    setEngagementLevel(1);
  }
}, [messages, engagementLevel, setEngagementLevel]);

