import { useState } from "react";

import { useOnboarding } from "../onboarding/context";
import { useStudio } from "../state/StudioContext";
import type { StudioConfig } from "../types";
import { useUpdater } from "./updater/useUpdater";

export function SettingsPanel() {
  const {
    settings,
    saveSettings,
    clearChat,
    refreshCanvas,
    pushToast,
    memory,
  } = useStudio();
  const { enabled: tourEnabled, restart: restartTour } = useOnboarding();
  const [open, setOpen] = useState(true);
  const updater = useUpdater();

  function update<K extends keyof StudioConfig>(key: K, value: StudioConfig[K]): void {
    saveSettings({ ...settings, [key]: value });
  }

  return (
    <section id="studio-settings" className="settings-drawer" aria-label="Studio settings">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <h2 className="section-title">Studio settings</h2>
          <p className="caption" style={{ marginBottom: 0 }}>
            Your workspace, your model, and what I've learned. All on this machine.
          </p>
        </div>
        <button
          type="button"
          className="studio-button studio-button--ghost"
          aria-expanded={open}
          aria-controls="studio-controls-body"
          onClick={() => setOpen((prev) => !prev)}
        >
          {open ? "Hide" : "Show"}
        </button>
      </div>

      {open && (
        <div id="studio-controls-body" style={{ marginTop: 14 }}>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 14 }}>
            <button type="button" className="studio-button" onClick={clearChat}>
              New conversation
            </button>
            <button
              type="button"
              className="studio-button"
              onClick={() => void refreshCanvas()}
            >
              Refresh workspace
            </button>
            {tourEnabled ? (
              <button type="button" className="studio-button" onClick={restartTour}>
                Replay the welcome
              </button>
            ) : null}
          </div>

          <p className="caption">
            I'm carrying {memory.length} {memory.length === 1 ? "thing" : "things"} for you. You can
            correct or forget any of it in <strong>What I've learned</strong>.
          </p>

          <details>
            <summary style={{ cursor: "pointer" }}>Model connection</summary>
            <div style={{ marginTop: 10 }}>
              <div className="studio-field">
                <label htmlFor="base-url">Model address</label>
                <input
                  id="base-url"
                  className="studio-input"
                  value={settings.base_url}
                  onChange={(event) => update("base_url", event.target.value)}
                />
              </div>
              <div className="studio-field">
                <label htmlFor="api-key">API key</label>
                <input
                  id="api-key"
                  className="studio-input"
                  type="password"
                  autoComplete="off"
                  value={settings.api_key}
                  onChange={(event) => update("api_key", event.target.value)}
                />
              </div>
              <div className="studio-field">
                <label htmlFor="model-name">Model name</label>
                <input
                  id="model-name"
                  className="studio-input"
                  value={settings.model_name}
                  onChange={(event) => update("model_name", event.target.value)}
                />
              </div>
            </div>
          </details>

          <details style={{ marginTop: 10 }}>
            <summary style={{ cursor: "pointer" }}>Workspace connection</summary>
            <div style={{ marginTop: 10 }}>
              <div className="studio-field">
                <label htmlFor="mcp-url">Workspace address</label>
                <input
                  id="mcp-url"
                  className="studio-input"
                  value={settings.mcp_url}
                  onChange={(event) => update("mcp_url", event.target.value)}
                />
              </div>
              <p className="caption">
                The local service that holds your opportunities, evidence, and decisions.
              </p>
            </div>
          </details>

          <details style={{ marginTop: 10 }}>
            <summary style={{ cursor: "pointer" }}>About The Living Studio</summary>
            <p className="caption" style={{ marginTop: 8 }}>
              The Living Studio helps product managers choose and win the next opportunity that
              matters — to their customers, their business, and their career. It listens for your
              intent, translates it into rigorous structures underneath, and shows its work.
              <br />
              Your conversations and notes stay on this machine. Only the compact context needed
              for a reply is sent to the model you choose.
            </p>
            <div style={{ marginTop: 8 }}>
              <button
                type="button"
                className="studio-button"
                disabled={updater.checking}
                onClick={() => {
                  void updater.check();
                  if (updater.error) {
                    pushToast("info", updater.error);
                  }
                }}
              >
                {updater.checking ? "Checking for updates…" : "Check for updates"}
              </button>
              {updater.available && updater.version && (
                <span className="source-badge">v{updater.version}</span>
              )}
              {updater.progress !== null && (
                <span className="source-badge">
                  {Math.round((updater.progress ?? 0) * 100)}%
                </span>
              )}
              {updater.error && <span className="source-badge">{updater.error}</span>}
            </div>
          </details>
        </div>
      )}
    </section>
  );
}

import { useMemo, useState } from "react";

import { isUnderserved } from "../../lib/odi";
import { useStudio } from "../../state/StudioContext";
import { GhostMetrics, GhostOpportunityCards } from "../Skeletons";
import { OutcomeCard } from "./OutcomeCard";

export function OpportunityLandscape() {
  const { canvas, canvasLoading } = useStudio();
  const [underservedOnly, setUnderservedOnly] = useState(false);
  const [sorted, setSorted] = useState(false);

  const jobs = useMemo(() => canvas?.jobs ?? [], [canvas]);
  const outcomes = useMemo(() => canvas?.outcomes ?? [], [canvas]);

  const underservedCount = outcomes.filter((outcome) =>
    isUnderserved(outcome.opportunity_score),
  ).length;

  const visible = useMemo(() => {
    const filtered = underservedOnly
      ? outcomes.filter((outcome) => isUnderserved(outcome.opportunity_score))
      : [...outcomes];
    if (sorted) {
      filtered.sort(
        (a, b) => (b.opportunity_score ?? -Infinity) - (a.opportunity_score ?? -Infinity),
      );
    }
    return filtered;
  }, [outcomes, underservedOnly, sorted]);

  return (
    <section className="fade-in">
      <h2 className="section-title">Your next move</h2>
      <p className="caption">
        The opportunities in play, and the evidence behind them. The strongest gaps rise to the top.
      </p>

      {canvasLoading && !canvas ? (
        <GhostMetrics />
      ) : (
        <div className="metric-grid">
          <div className="studio-metric">
            <div className="studio-metric__label">Opportunities</div>
            <div className="studio-metric__value">{outcomes.length}</div>
          </div>
          <div className="studio-metric">
            <div className="studio-metric__label">Worth pursuing</div>
            <div className="studio-metric__value">{underservedCount}</div>
            <div className="studio-metric__delta">Strong gaps</div>
          </div>
          <div className="studio-metric">
            <div className="studio-metric__label">Parts of the work</div>
            <div className="studio-metric__value">{jobs.length}</div>
          </div>
        </div>
      )}

      <div style={{ display: "flex", gap: 12, marginBottom: 12, flexWrap: "wrap" }}>
        <label style={{ fontSize: "0.82rem", color: "var(--studio-muted)" }}>
          <input
            type="checkbox"
            checked={sorted}
            onChange={(event) => setSorted(event.target.checked)}
          />{" "}
          Strongest gaps first
        </label>
        <label style={{ fontSize: "0.82rem", color: "var(--studio-muted)" }}>
          <input
            type="checkbox"
            checked={underservedOnly}
            onChange={(event) => setUnderservedOnly(event.target.checked)}
          />{" "}
          Only the underserved
        </label>
      </div>

      <hr style={{ borderColor: "var(--studio-border)" }} />

      {canvasLoading && !canvas ? (
        <GhostOpportunityCards />
      ) : visible.length ? (
        visible.map((outcome, index) => (
          <OutcomeCard outcome={outcome} key={outcome.id ?? index} />
        ))
      ) : (
        <p className="caption">No opportunities match this view yet. Ask the copilot to find one.</p>
      )}
    </section>
  );
}

import { isUnderserved, opportunityPill } from "../../lib/odi";
import { useStudio } from "../../state/StudioContext";
import type { Outcome } from "../../types";

export function OutcomeCard({ outcome }: { outcome: Outcome }) {
  const { requestSimulate, sendMessage, pushToast } = useStudio();

  const opp = outcome.opportunity_score;
  const imp = outcome.importance;
  const sat = outcome.satisfaction;
  const statement = outcome.statement ?? "Untitled opportunity";
  const outcomeId = outcome.id ?? "O";
  const underserved = isUnderserved(opp);
  const pill = opportunityPill(opp);

  return (
    <>
      <article
        className={`outcome-card fade-in${underserved ? " pulsing-card" : ""}`}
        aria-label={`Opportunity ${outcomeId}`}
      >
        <div className="outcome-card__head">
          <span className="outcome-card__id">{outcomeId}</span>
          <span className={`studio-pill pill-${pill.variant}`}>{pill.label}</span>
        </div>
        <div className="outcome-card__statement">&quot;{statement}&quot;</div>
        <div className="outcome-card__meta">
          Matters to customers: <b>{imp != null ? imp : "—"}/10</b> &nbsp;|&nbsp; Handled well
          today: <b>{sat != null ? sat : "—"}/10</b>
        </div>
        <details className="outcome-card__formula">
          <summary>Show the ODI view</summary>
          <p>
            Opportunity score: <i>importance + max(importance − satisfaction, 0)</i>
            {opp != null ? ` = ${opp.toFixed(2)}` : " — not scored yet"}.
          </p>
        </details>
      </article>

      <div className="outcome-card__actions">
        <button
          type="button"
          className="studio-button"
          onClick={() =>
            pushToast(
              "info",
              `Evidence behind ${outcomeId}:\n\n${outcome.evidence ?? "No evidence linked yet."}`,
            )
          }
        >
          View evidence
        </button>
        <button
          type="button"
          className="studio-button"
          onClick={() => {
            requestSimulate(outcomeId);
            pushToast("success", `${outcomeId} is ready to pressure-test.`);
          }}
        >
          Pressure-test this
        </button>
        <button
          type="button"
          className="studio-button"
          onClick={() => void sendMessage(`How should we solve ${outcomeId}: '${statement}'?`)}
        >
          Ask the copilot
        </button>
      </div>
    </>
  );
}

import { useState } from "react";

import { useStudio } from "../../state/StudioContext";
import { GhostJobSteps } from "../Skeletons";

export function JobMap() {
  const { canvas, canvasLoading, addStep } = useStudio();
  const [stepName, setStepName] = useState("");
  const [stepOrder, setStepOrder] = useState<number | null>(null);
  const [busy, setBusy] = useState(false);

  const steps = canvas?.steps ?? [];
  const jobs = canvas?.jobs ?? [];
  const activeJobId = jobs[0]?.id ?? "JOB-402";
  const defaultOrder = steps.length + 1;

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!stepName.trim() || busy) {
      return;
    }
    setBusy(true);
    try {
      await addStep({ job_id: activeJobId, name: stepName.trim(), order: stepOrder ?? defaultOrder });
      setStepName("");
      setStepOrder(null);
    } finally {
      setBusy(false);
    }
  }

  return (
    <section>
      <h2 className="section-title">How the work happens</h2>
      <p className="caption">
        The steps your customer goes through today. The friction usually lives in one of them.
      </p>

      {canvasLoading && !canvas ? (
        <GhostJobSteps />
      ) : steps.length ? (
        steps.map((step, index) => (
          <div className="step-row fade-in" key={step.id ?? index}>
            <b>Step {step.order ?? ""}</b>: {step.name ?? ""}
          </div>
        ))
      ) : (
        <p className="toast toast--info" role="status">
          No steps yet. Ask the copilot to walk through how the work happens today.
        </p>
      )}

      <details style={{ marginTop: 14 }}>
        <summary style={{ cursor: "pointer" }}>Add a step</summary>
        <form onSubmit={submit} style={{ marginTop: 10 }}>
          <div className="studio-field">
            <label htmlFor="step-name">What happens in this step?</label>
            <input
              id="step-name"
              className="studio-input"
              placeholder="e.g. Check that the last change is safe to ship"
              value={stepName}
              onChange={(event) => setStepName(event.target.value)}
            />
          </div>
          <div className="studio-field">
            <label htmlFor="step-order">Where does it happen?</label>
            <input
              id="step-order"
              className="studio-input"
              type="number"
              min={1}
              max={20}
              value={stepOrder ?? defaultOrder}
              onChange={(event) => setStepOrder(Number(event.target.value))}
            />
          </div>
          <button type="submit" className="studio-button" disabled={busy || !stepName.trim()}>
            Add this step
          </button>
        </form>
      </details>

      <details style={{ marginTop: 14 }}>
        <summary style={{ cursor: "pointer" }}>Show the ODI view</summary>
        <p className="caption" style={{ marginTop: 8 }}>
          The eight universal stages are Define, Locate, Prepare, Confirm, Execute, Monitor, Modify,
          and Conclude. They are a lens for finding where the work breaks, not a script for the
          conversation.
        </p>
      </details>
    </section>
  );
}

import { useMemo, useState } from "react";

import { useStudio } from "../../state/StudioContext";

export function ImpactSim() {
  const { canvas, sendMessage, pushToast, pendingSimOutcome, clearPendingSimOutcome } = useStudio();

  const outcomes = useMemo(() => canvas?.outcomes ?? [], [canvas]);
  const options = useMemo(
    () =>
      outcomes.map(
        (outcome) => `${outcome.id ?? "O"}: ${outcome.statement ?? "Untitled opportunity"}`,
      ),
    [outcomes],
  );

  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [bet, setBet] = useState("A zero-touch secret sync that follows the deploy, not the calendar");

  const pendingOption = useMemo(
    () =>
      pendingSimOutcome
        ? options.find((option) => option.startsWith(`${pendingSimOutcome}:`))
        : undefined,
    [pendingSimOutcome, options],
  );
  const selected =
    pendingOption ??
    (selectedOption && options.includes(selectedOption) ? selectedOption : options[0] ?? "");

  function onSelect(value: string) {
    setSelectedOption(value);
    if (pendingSimOutcome) {
      clearPendingSimOutcome();
    }
  }

  async function declare() {
    await sendMessage(
      `Pressure-test this bet: '${bet}' against '${selected}'. What has to be true, and what evidence do we have?`,
    );
    pushToast("success", "Asked the copilot to pressure-test it.");
  }

  return (
    <section>
      <h2 className="section-title">What changes if we do this</h2>
      <p className="caption">
        An example of the before-and-after view. Ask the copilot to simulate your own bet.
