          id="sim-bet"
          className="studio-input"
          value={bet}
          onChange={(event) => setBet(event.target.value)}
        />
      </div>

      <h3 className="section-title" style={{ fontSize: "0.95rem" }}>
        Example: before and after
      </h3>
      <div className="studio-form-grid">
        <div
          className="fade-in"
          style={{
            background: "rgba(239, 68, 68, 0.08)",
            border: "1px solid rgba(239, 68, 68, 0.2)",
            padding: 14,
            borderRadius: 8,
          }}
        >
          <span
            className="studio-pill"
            style={{ background: "rgba(239,68,68,0.2)", color: "#f87171" }}
          >
            Today
          </span>
          <ul style={{ marginTop: 8, fontSize: "0.88rem", color: "#cbd5e1" }}>
            <li>
              <b>45 minutes</b> of manual copy-paste per rotation.
            </li>
            <li>
              <b>14% of deploys fail</b> on configuration drift.
            </li>
            <li>400 teams carry the same manual ritual.</li>
          </ul>
        </div>
        <div
          className="fade-in"
          style={{
            background: "rgba(16, 185, 129, 0.08)",
            border: "1px solid rgba(16, 185, 129, 0.2)",
            padding: 14,
            borderRadius: 8,
          }}
        >
          <span className="studio-pill pill-green">If this works</span>
          <ul style={{ marginTop: 8, fontSize: "0.88rem", color: "#cbd5e1" }}>
            <li>
              <b>Under 30 seconds</b>, ambient and unattended.
            </li>
