import { useMemo, useState } from "react";

import { isUnderserved, opportunityScore } from "../../lib/odi";
import { useStudio } from "../../state/StudioContext";

export function DirectCapture() {
  const { canvas, addOutcome } = useStudio();
  const jobs = canvas?.jobs ?? [];

  const [jobId, setJobId] = useState<string | null>(null);
  const [statement, setStatement] = useState("");
  const [importance, setImportance] = useState(8.5);
  const [satisfaction, setSatisfaction] = useState(3.5);
  const [busy, setBusy] = useState(false);

  const activeJobId = jobId ?? jobs[0]?.id ?? "";

  const gap = useMemo(
    () => opportunityScore(importance, satisfaction),
    [importance, satisfaction],
  );

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!statement.trim() || !activeJobId || busy) {
      return;
    }
    setBusy(true);
    try {
      await addOutcome({
        job_id: activeJobId,
        statement: statement.trim(),
        importance,
        satisfaction,
      });
      setStatement("");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section>
      <h2 className="section-title">Add what you know</h2>
      <p className="caption">
        Capture an opportunity in your own words. The copilot can sharpen it into a thesis.
      </p>

      <form onSubmit={submit}>
        <div className="studio-field">
          <label htmlFor="dc-job">Which part of the work?</label>
          <select
            id="dc-job"
            className="studio-select"
            value={activeJobId}
            onChange={(event) => setJobId(event.target.value)}
          >
            {jobs.map((job) => (
              <option key={job.id} value={job.id}>
                {job.id}: {job.name ?? ""}
              </option>
            ))}
          </select>
        </div>

        <div className="studio-field">
          <label htmlFor="dc-statement">What does better look like?</label>
          <input
            id="dc-statement"
            className="studio-input"
            placeholder="e.g. New engineers can ship their first change without asking for help"
            value={statement}
            onChange={(event) => setStatement(event.target.value)}
          />
          <p className="caption" style={{ marginTop: 4 }}>
            Say it the way you would say it. You can refine the wording with the copilot.
          </p>
        </div>

        <div className="studio-form-grid">
          <div className="studio-field">
            <label htmlFor="dc-importance">How much does it matter? {importance.toFixed(1)}/10</label>
            <input
              id="dc-importance"
              type="range"
              min={1}
              max={10}
              step={0.1}
              value={importance}
              onChange={(event) => setImportance(Number(event.target.value))}
            />
          </div>
          <div className="studio-field">
            <label htmlFor="dc-satisfaction">
              How well is it handled today? {satisfaction.toFixed(1)}/10
            </label>
            <input
              id="dc-satisfaction"
              type="range"
              min={1}
              max={10}
              step={0.1}
              value={satisfaction}
              onChange={(event) => setSatisfaction(Number(event.target.value))}
            />
          </div>
        </div>

        <p className="toast toast--info" role="status" style={{ marginBottom: 12 }}>
          <b>Where the gap is:</b>{" "}
          {isUnderserved(gap) ? "wide open — worth a closer look" : "mostly covered today"}.
        </p>

        <button type="submit" className="studio-button" disabled={busy || !statement.trim()}>
          Add this opportunity
        </button>
      </form>
    </section>
  );
}

import type { GoalIconName } from "./icons";

